String base(def p) { if (p == null) { return null; } String s = p.toString(); int a = s.lastIndexOf('\\'); int b = s.lastIndexOf('/'); return s.substring((a > b ? a : b) + 1); }
if (ctx.process != null) {
  if (ctx.process.executable != null && ctx.process.name == null) { ctx.process.name = base(ctx.process.executable); }
  if (ctx.process.parent != null && ctx.process.parent.executable != null) { ctx.process.parent.name = base(ctx.process.parent.executable); }
}
if (ctx.file != null && ctx.file.path != null) { ctx.file.name = base(ctx.file.path); }
